<span class="line"><span style="color:#61AFEF;">sudo</span><span style="color:#98C379;"> usermod</span><span style="color:#D19A66;"> -aG</span><span style="color:#98C379;"> sudo</span><span style="color:#98C379;"> devuser</span><span style="color:#7F848E;font-style:italic;">    # Ubuntu</span></span>
